def main():
 queue=json.loads(QUEUE.read_text(encoding='utf-8'))['unresolved_rows']
 for domain_id,decisions_by_key in REVIEWS.items():
  rows=[r for r in queue if r['domain_id']==domain_id]; by={r['role_key']:r for r in rows}
  if len(by)!=len(rows) or set(by)!=set(decisions_by_key): raise SystemExit(f'{domain_id} exact-key mismatch; refusing partial generation.')
  decisions=[]
  for key,(fit,why,refs) in decisions_by_key.items():
   r=by[key]; decisions.append({'role_key':key,'role_name':r['role_name'],'task_evidence':r['role_description'],'esco_uri':(r.get('esco_occupation_uris') or [None])[0],'onet_codes':r.get('onet_occupation_codes',[]),'domain_fit':fit,'rationale':why,'source_refs':refs})
  tally=Counter(x['domain_fit'] for x in decisions)
  corrections=[]
  for row in decisions:
   if row['domain_fit']==U:
    corrections.append({'role_key':row['role_key'],'action':'remove_from_parent_domain','candidate_transfer_domain':None,'evidence_basis':row['rationale'],'canonical_change_made':False})
  payload={'schema_version':'1.0','audit_date':date.today().isoformat(),'domain_id':domain_id,'domain_name':rows[0]['domain_name'],'scope':rows[0]['domain_scope'],'method':'Exact-key comparison of each stored task with this parent-domain scope. No transfer of disposition across same-named roles in another domain; titles, ISCO/subgroup and frequency do not establish fit. Conditional means the role may fit only with portfolio/task evidence. No role-to-specialization assignment is made. Global finance/credit sources clarify functions; jurisdiction-specific rules are not generalized.','counts':{'mappings_reviewed':len(decisions),'supported':tally[S],'conditional':tally[C],'unsupported_for_domain':tally[U],'unresolved':tally[R]},'decisions':decisions,'sources':SOURCES,'correction_proposals':corrections,'separate_coverage_candidates':[],'notes':['D158 corporate finance/investment banking is distinct from D159 borrower-credit assessment; similarly titled records were judged independently against each parent.','U.S. mortgage-broker and professional career sources clarify role functions only; they do not establish licensing or credential rules outside their jurisdictions.','No Nigeria-specific variant was inferred from the global records.','No canonical role/domain/subgroup data or role-to-specialization assignment was changed.']}
  stem=f'{domain_id}_role_domain_fit_review_2026_10_05'; (LANE/f'{stem}.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
  lines=[f"# {domain_id} role-to-parent-domain fit review — {payload['audit_date']}",'',f"Scope: {payload['scope']}",'',f"- Exact queued roles reviewed: **{len(decisions)}**",f"- Supported: **{tally[S]}**",f"- Conditional: **{tally[C]}**",f"- Unsupported for this parent: **{tally[U]}**",f"- Unresolved: **{tally[R]}**",'','| Exact role key | Recorded task evidence | Parent fit | Rationale |','|---|---|---|---|']
  for x in decisions: lines.append(f"| `{x['role_key']}` | {x['task_evidence'].replace('|','\\|').replace(chr(10),' ')} | {x['domain_fit']} | {x['rationale'].replace('|','\\|')} |")
  lines+=['','## Non-canonical correction proposals','']+[f"- `{x['role_key']}` — remove from parent domain: {x['evidence_basis']} No canonical change made." for x in corrections]+['','## Sources and limitations','']+[f"- **{k} — {v['publisher']}**: [{v['url']}]({v['url']}). {v['locator']} Supports: {v['supports']} Limit: {v['limit']}" for k,v in SOURCES.items()]+['','## Audit notes','']+[f'- {n}' for n in payload['notes']]
  (LANE/f'{domain_id}_role_domain_fit_review_2026_10_05.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
  print(domain_id,json.dumps(payload['counts']))
if __name__=='__main__': main()
